CREATE TABLE "Role" (
    "id" integer PRIMARY KEY,
    "name" varchar(50) NOT NULL UNIQUE
);

INSERT INTO "Role" ("id", "name") VALUES
    (1, 'CITIZEN'),
    (2, 'OPERATOR'),
    (3, 'TECHNICIAN');

CREATE TABLE "User" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar(100) NOT NULL,
    "email" varchar(254) NOT NULL UNIQUE,
    "password_hash" varchar(60) NOT NULL,
    "role_id" integer NOT NULL,
    CONSTRAINT "fk_user_role"
        FOREIGN KEY ("role_id") REFERENCES "Role" ("id"),
    CONSTRAINT "ck_user_email_lowercase"
        CHECK ("email" = lower("email"))
);

COMMENT ON COLUMN "User"."email" IS
    'Stored in lower case, so the unique constraint is case-insensitive.';

-- Supports listing the users of one role ordered by name, then id (technicians list).
CREATE INDEX "idx_user_role_id_name_id"
    ON "User" ("role_id", "name", "id");

ALTER TABLE "Incident"
    ADD COLUMN "reporter_id" integer,
    ADD CONSTRAINT "fk_incident_reporter"
        FOREIGN KEY ("reporter_id") REFERENCES "User" ("id");

COMMENT ON COLUMN "Incident"."reporter_id" IS
    'Citizen who reported the incident. Null only for incidents stored before authentication.';

-- Supports listing the incidents of one reporter, newest first.
CREATE INDEX "idx_incident_reporter_id_created_at"
    ON "Incident" ("reporter_id", "created_at");
